-- 观看次数按ad_log全部结果记录统计，不再只取成功完播；完播限定result='1'。
SELECT a.day AS "数据日期",coalesce(ac.active_users,0) AS "当日活跃",a.ad_point AS "广告点名称",a.view_count AS "视频观看次数",a.complete_count AS "视频完播次数",a.viewers AS "观看人数",a.completers AS "完播人数",round(1.000000*a.view_count/nullif(a.viewers,0),2) AS "人均观看次数",round(1.000000*a.complete_count/nullif(a.completers,0),2) AS "人均完播次数",cast(round(1.000000*a.complete_count/nullif(a.view_count,0),4) AS decimal(18,4)) AS "完播率%",cast(round(1.000000*a.complete_count/nullif(dt.complete_count,0),4) AS decimal(18,4)) AS "完播占比%",cast(round(1.000000*a.completers/nullif(dt.completers,0),4) AS decimal(18,4)) AS "完播人数占比%",cast(round(1.000000*a.viewers/nullif(ac.active_users,0),4) AS decimal(18,4)) AS "渗透率%" FROM (SELECT day,ad_point,count(*) view_count,count_if(ad_result='1') complete_count,count(DISTINCT pid) viewers,count(DISTINCT CASE WHEN ad_result='1' THEN pid END) completers FROM (SELECT * FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id,e."$part_event" event_name,coalesce(nullif(e.ad_location_scene,''),nullif(e.ad_location_name,''),nullif(e.ad_location_id,''),'未知广告点') ad_point,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.result ad_result,e.battle_result,e.battle_time,e.remain_screw_num,e."#duration" seconds FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) population WHERE ${Selector:selector4}) e WHERE event_name='ad_log' AND ('${Variable5}'='全部' OR ad_point='${Variable5}')) e GROUP BY day,ad_point) a LEFT JOIN (SELECT day,count(DISTINCT pid) active_users FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id,e."$part_event" event_name,coalesce(nullif(e.ad_location_scene,''),nullif(e.ad_location_name,''),nullif(e.ad_location_id,''),'未知广告点') ad_point,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.result ad_result,e.battle_result,e.battle_time,e.remain_screw_num,e."#duration" seconds FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) population WHERE ${Selector:selector4}) e GROUP BY day) ac ON a.day=ac.day LEFT JOIN (SELECT day,count(*) view_count,count_if(ad_result='1') complete_count,count(DISTINCT pid) viewers,count(DISTINCT CASE WHEN ad_result='1' THEN pid END) completers FROM (SELECT * FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id,e."$part_event" event_name,coalesce(nullif(e.ad_location_scene,''),nullif(e.ad_location_name,''),nullif(e.ad_location_id,''),'未知广告点') ad_point,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.result ad_result,e.battle_result,e.battle_time,e.remain_screw_num,e."#duration" seconds FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) population WHERE ${Selector:selector4}) e WHERE event_name='ad_log' AND ('${Variable5}'='全部' OR ad_point='${Variable5}')) e GROUP BY day) dt ON a.day=dt.day ORDER BY a.day DESC,a.complete_count DESC,a.ad_point